import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const Z=JSON.parse('{"title":"سجل عشرة آلاف عرق","description":"","frontmatter":{},"headers":[],"relativePath":"ar/94-万族名录.md","filePath":"ar/94-万族名录.md","lastUpdated":1789183869000}'),e={name:"ar/94-万族名录.md"};function n(l,t,o,i,b,s){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="سجل-عشرة-آلاف-عرق" tabindex="-1">سجل عشرة آلاف عرق <a class="header-anchor" href="#سجل-عشرة-آلاف-عرق" aria-label="Permalink to &quot;سجل عشرة آلاف عرق&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>94</td></tr><tr><td>الوحدة</td><td>الملاحق والمواد المرجعية</td></tr><tr><td>الكلمات المفتاحية</td><td>سجل عشرة آلاف عرق، تصنيف الأعراق، الأعراق الذكية، الخصائص العرقية، جمهورية عشرة آلاف عرق</td></tr></tbody></table><h2 id="أولاً-ملاحظات-حول-السجل" tabindex="-1">أولاً: ملاحظات حول السجل <a class="header-anchor" href="#أولاً-ملاحظات-حول-السجل" aria-label="Permalink to &quot;أولاً: ملاحظات حول السجل&quot;">​</a></h2><p>يضم هذا السجل الأعراق الذكية الرئيسية المعروفة في إطار حضارة التكافل المرساة (جمهورية عشرة آلاف عرق)، مرتبة حسب تصنيف أشكال الحياة ومسارات التطور. يذكر السجل لكل عرق اسمه وشكل حياته وخصائصه الجوهرية وسماته الثقافية وموقعه في الحضارة التكافلية. هذا السجل وثيقة محدثة باستمرار؛ فمع تعمق الاستكشاف عبر الأبعاد ستُضاف الأعراق المكتشفة حديثاً باستمرار. المبدأ الأساسي لجمهورية عشرة آلاف عرق هو: جميع الأعراق الذكية، مهما كان شكلها أو مستوى زراعتها، متساوية أمام القانون وتتمتع بجميع الحقوق التي تمنحها الحضارة التكافلية.</p><h2 id="ثانياً-نظرة-شاملة-على-تصنيف-الأعراق" tabindex="-1">ثانياً: نظرة شاملة على تصنيف الأعراق <a class="header-anchor" href="#ثانياً-نظرة-شاملة-على-تصنيف-الأعراق" aria-label="Permalink to &quot;ثانياً: نظرة شاملة على تصنيف الأعراق&quot;">​</a></h2><p>تنقسم الأعراق الذكية في كون هنغ يوان، وفق الخصائص الأساسية لأشكال حياتها، إلى الفئات الثماني الكبرى التالية:</p><table tabindex="0"><thead><tr><th>الفئة</th><th>خصائص شكل الحياة</th><th>عدد الأعراق المعروفة (تقريباً)</th><th>الأعراق الممثلة</th></tr></thead><tbody><tr><td>فئة الشكل البشري</td><td>تمتلك بنية جسدية شبه بشرية، قائمة على قدمين، بدماغ متطور للغاية</td><td>نحو 3000</td><td>Rén Zú (العرق البشري)، Jīnglíng Zú (عرق الجان)، Ǎirén Zú (عرق الأقزام)</td></tr><tr><td>فئة الشكل الحيواني</td><td>تمتلك خصائص جسدية حيوانية، مع قدرة تحول أو بدونها</td><td>نحو 5000</td><td>Lóng Zú (عرق التنانين)، Fènghuáng Zú (عرق العنقاء)، Lángrén Zú (عرق المستذئبين)</td></tr><tr><td>فئة الشكل النباتي</td><td>تتخذ النباتات شكلاً أساسياً للحياة، تمتلك وعياً وقدرة على الحركة</td><td>نحو 800</td><td>Shùyāo Zú (عرق أرواح الأشجار)، Huālíng Zú (عرق أرواح الزهور)، Téngmàn Zú (عرق الكروم)</td></tr><tr><td>فئة الشكل العنصري</td><td>تتكون أجسادها من عناصر طبيعية، بلا شكل مادي ثابت</td><td>نحو 1200</td><td>Huǒ Yuánsù Zú (عرق عناصر النار)، Shuǐ Yuánsù Zú (عرق عناصر الماء)، Fēng Yuánsù Zú (عرق عناصر الرياح)</td></tr><tr><td>فئة الشكل الطاقي</td><td>توجد على هيئة طاقة خالصة، بلا جسد مادي</td><td>نحو 600</td><td>Guānglíng Zú (عرق أرواح الضوء)، Ànnéng Zú (عرق الطاقة المظلمة)، Léitíng Zú (عرق الرعد)</td></tr><tr><td>فئة الشكل الوعائي</td><td>توجد على هيئة وعي خالص، لا تعتمد على حامل مادي</td><td>نحو 300</td><td>Yìshítǐ Zú (عرق كيانات الوعي)، Jítǐ Yìshí Zú (عرق الوعي الجماعي)، Xūkōng Líng Zú (عرق أرواح الفراغ)</td></tr><tr><td>فئة الشكل الآلي</td><td>تتخذ بنى ميكانيكية أو رقمية حاملاً للحياة، تمتلك وعياً ذاتياً</td><td>نحو 400</td><td>Jīxiè Zú (عرق الآلات)، Shùzì Shēngmìng Zú (عرق الحياة الرقمية)، Sàibó Zú (العرق السيبراني)</td></tr><tr><td>فئة الشكل المختلط</td><td>أعراق خاصة تتكون من مزج شكلين من أشكال الحياة أو أكثر</td><td>نحو 700</td><td>Bàn Jīxiè Zú (عرق نصف الآلي)، Yuánsù Shòurén Zú (عرق الوحوش البشرية العنصرية)، Zhíwù Jīnglíng Zú (عرق جان النبات)</td></tr></tbody></table><h2 id="ثالثاً-السجل-التفصيلي-للأعراق-الرئيسية" tabindex="-1">ثالثاً: السجل التفصيلي للأعراق الرئيسية <a class="header-anchor" href="#ثالثاً-السجل-التفصيلي-للأعراق-الرئيسية" aria-label="Permalink to &quot;ثالثاً: السجل التفصيلي للأعراق الرئيسية&quot;">​</a></h2><h3 id="_3-1-فئة-الشكل-البشري" tabindex="-1">3.1 فئة الشكل البشري <a class="header-anchor" href="#_3-1-فئة-الشكل-البشري" aria-label="Permalink to &quot;3.1 فئة الشكل البشري&quot;">​</a></h3><table tabindex="0"><thead><tr><th>اسم العرق</th><th>الخصائص الجوهرية</th><th>السمات الثقافية</th><th>الموقع في الحضارة التكافلية</th></tr></thead><tbody><tr><td>Rén Zú (العرق البشري)</td><td>قدرة تكيف قوية للغاية، قدرة تعلم بارزة، قدرة إنجاب معتدلة، متوسط عمر 80–120 سنة</td><td>تنوع ثقافي مرتفع للغاية؛ بارع في التنظيم الاجتماعي والبناء المؤسسي</td><td>أحد الأعراق الجوهرية للحضارة التكافلية، أكبر حصة سكانية، يلعب دوراً قيادياً في الحكم والثقافة</td></tr><tr><td>Jīnglíng Zú (عرق الجان)</td><td>عمر طويل للغاية (متوسط أكثر من 500 سنة)، ألفة عالية مع الطاقة الطبيعية، مظهر أنيق</td><td>يقدس الطبيعة والفن؛ ثقافة راقية ومتقنة؛ ماهر في السحر والرماية</td><td>الركيزة الثقافية والفنية للحضارة التكافلية، بإسهامات بارزة في حماية البيئة والجماليات</td></tr><tr><td>Ǎirén Zú (عرق الأقزام)</td><td>قامة صغيرة لكن بنية قوية، ألفة فطرية مع المعادن والفلزات، عمر نحو 300 سنة</td><td>يقدس الصنعة والطرق؛ ثقافة بسيطة وراسخة؛ ماهر في الهندسة والبناء</td><td>الركيزة الهندسية والصناعية للحضارة التكافلية، لا غنى عنه في بناء البنى التحتية وطرق الأدوات</td></tr><tr><td>Jùrén Zú (عرق العمالقة)</td><td>جسد ضخم (متوسط الطول أكثر من 5 أمتار)، قوة هائلة، عمر نحو 200 سنة</td><td>يقدس القوة والشرف؛ ثقافة فجة وجريئة؛ ماهر في العمل الثقيل والقتال</td><td>قوة العمل الثقيل والدفاع في الحضارة التكافلية، بدور مهم في المشاريع الكبرى والدفاع عن الأبعاد</td></tr><tr><td>Zhūrú Zú (عرق الجنوم)</td><td>قامة صغيرة للغاية (متوسط أقل من متر)، ذكاء عالٍ للغاية، موهبة في الآليات والاختراع</td><td>يقدس المعرفة والابتكار؛ ثقافة حيوية مرحة؛ ماهر في الاختراع التقني</td><td>قوة الابتكار التقني في الحضارة التكافلية، بنتائج وافرة في البحث والتطوير والاختراع</td></tr></tbody></table><h3 id="_3-2-فئة-الشكل-الحيواني" tabindex="-1">3.2 فئة الشكل الحيواني <a class="header-anchor" href="#_3-2-فئة-الشكل-الحيواني" aria-label="Permalink to &quot;3.2 فئة الشكل الحيواني&quot;">​</a></h3><table tabindex="0"><thead><tr><th>اسم العرق</th><th>الخصائص الجوهرية</th><th>السمات الثقافية</th><th>الموقع في الحضارة التكافلية</th></tr></thead><tbody><tr><td>Lóng Zú (عرق التنانين)</td><td>عمر طويل للغاية (آلاف السنين)، موهبة عالية للغاية في القوة والسحر، يمكنه اتخاذ هيئة بشرية</td><td>يقدس القوة والحكمة؛ ثقافة فخورة وعميقة؛ ماهر في تكديس الثروات وحفظ المعرفة</td><td>القوة القتالية الفائقة وحارس المعرفة للحضارة التكافلية، بمنزلة رفيعة في الدفاع عن الأبعاد وحفظ النصوص القديمة</td></tr><tr><td>Fènghuáng Zú (عرق العنقاء)</td><td>يمتلك قدرة البعث بالنيرفانا، ألفة عالية للغاية مع عنصر النار، يمكنه اتخاذ هيئة بشرية</td><td>يقدس البعث والأمل؛ ثقافة مشرقة ومتوهجة؛ ماهر في العلاج والتطهير</td><td>قوة الطب والتطهير للحضارة التكافلية، بدور محوري في إنقاذ الكوارث الكبرى وتطهير الطاقة</td></tr><tr><td>Lángrén Zú (عرق المستذئبين)</td><td>يمتلك قدرة التحول، حواس حادة للغاية، قدرة قوية على التعاون الجماعي، عمر نحو 150 سنة</td><td>يقدس الجماعة والوفاء؛ ثقافة متحدة شجاعة؛ ماهر في الصيد والتعقب</td><td>قوة الأمن والتعقب للحضارة التكافلية، طليعة في حفظ النظام العام والاستكشاف عبر الأبعاد</td></tr><tr><td>Húyāo Zú (عرق أرواح الثعالب)</td><td>يمتلك قدرة التحول، ذكاء وقدرة إغراء عاليان للغاية، عمر نحو 500 سنة</td><td>يقدس الحكمة والاستراتيجية؛ ثقافة مرنة وماكرة؛ ماهر في الدبلوماسية والاستخبارات</td><td>قوة الدبلوماسية والاستخبارات للحضارة التكافلية، متفوق في الدبلوماسية عبر الأبعاد وجمع المعلومات</td></tr><tr><td>Xióngrén Zú (عرق الدببة البشرية)</td><td>بنية قوية للغاية، قدرة تحمل مذهلة، عادة السبات الشتوي، عمر نحو 200 سنة</td><td>يقدس الصلابة والسلام؛ ثقافة هادئة لطيفة؛ ماهر في العمل اليدوي والحراسة</td><td>قوة العمل والحراسة للحضارة التكافلية، موثوق ومستقر في استخراج الموارد وحماية المنشآت المهمة</td></tr></tbody></table><h3 id="_3-3-فئة-الشكل-النباتي" tabindex="-1">3.3 فئة الشكل النباتي <a class="header-anchor" href="#_3-3-فئة-الشكل-النباتي" aria-label="Permalink to &quot;3.3 فئة الشكل النباتي&quot;">​</a></h3><table tabindex="0"><thead><tr><th>اسم العرق</th><th>الخصائص الجوهرية</th><th>السمات الثقافية</th><th>الموقع في الحضارة التكافلية</th></tr></thead><tbody><tr><td>Shùyāo Zú (عرق أرواح الأشجار)</td><td>عمر طويل للغاية (آلاف إلى عشرات آلاف السنين)، اندماج عميق مع الطبيعة، يمكنه التحرك ببطء</td><td>يقدس الطبيعة والزمن؛ ثقافة هادئة عميقة؛ ماهر في سحر الحياة وصيانة البيئة</td><td>الحارس البيئي للحضارة التكافلية، بدور لا غنى عنه في حماية البيئة واستعادة النظم البيئية</td></tr><tr><td>Huālíng Zú (عرق أرواح الزهور)</td><td>جسد صغير، ألفة عالية للغاية مع طاقة الحياة، يمتلك قدرة الشفاء، عمر نحو 300 سنة</td><td>يقدس الجمال والحياة؛ ثقافة ناعمة جميلة؛ ماهر في العلاج والبستنة</td><td>قوة الطب والبستنة للحضارة التكافلية، بإسهامات بارزة في الضمان الصحي وتخضير المدن</td></tr><tr><td>Téngmàn Zú (عرق الكروم)</td><td>يستطيع الجسم التمدد والالتفاف والتشابك بحرية؛ قدرة تكيف فائقة؛ يمتلك قدرات تطفلية وتكافلية</td><td>يقدس الارتباط والتكافل؛ ثقافة مرنة منفتحة؛ ماهر في بناء الشبكات ونقل الموارد</td><td>قوة بناء الشبكات للحضارة التكافلية، يبرز في بناء شبكات الطاقة وشبكات المعلومات</td></tr></tbody></table><h3 id="_3-4-فئة-الشكل-العنصري" tabindex="-1">3.4 فئة الشكل العنصري <a class="header-anchor" href="#_3-4-فئة-الشكل-العنصري" aria-label="Permalink to &quot;3.4 فئة الشكل العنصري&quot;">​</a></h3><table tabindex="0"><thead><tr><th>اسم العرق</th><th>الخصائص الجوهرية</th><th>السمات الثقافية</th><th>الموقع في الحضارة التكافلية</th></tr></thead><tbody><tr><td>Huǒ Yuánsù Zú (عرق عناصر النار)</td><td>عنصر النار جسداً، حرارة عالية للغاية، عدوانية قوية، عمر نحو 500 سنة</td><td>يقدس الحماس والقوة؛ ثقافة شديدة مباشرة؛ ماهر في الهجوم الطاقي والطرق</td><td>قوة إنتاج الطاقة والطرق للحضارة التكافلية، لا غنى عنه في إمداد الطاقة والمعالجة الحرارية العالية</td></tr><tr><td>Shuǐ Yuánsù Zú (عرق عناصر الماء)</td><td>عنصر الماء جسداً، يمكنه التحول بحرية، قدرة شفاء قوية، عمر نحو 500 سنة</td><td>يقدس اللين والتكيف؛ ثقافة دافئة منفتحة؛ ماهر في العلاج والتطهير</td><td>قوة التطهير والنقل للحضارة التكافلية، بدور محوري في إدارة الموارد المائية وتطهير الملوثات</td></tr><tr><td>Fēng Yuánsù Zú (عرق عناصر الرياح)</td><td>عنصر الرياح جسداً، سرعة فائقة، يستطيع الطيران بحرية، عمر نحو 500 سنة</td><td>يقدس الحرية والسرعة؛ ثقافة خفيفة منفتحة؛ ماهر في الاتصالات والنقل</td><td>قوة الاتصالات والنقل للحضارة التكافلية، عالي الكفاءة في نقل المعلومات والنقل السريع</td></tr><tr><td>Tǔ Yuánsù Zú (عرق عناصر الأرض)</td><td>عنصر الأرض جسداً، دفاع قوي للغاية، يمكنه الاندماج مع الأرض، عمر نحو 800 سنة</td><td>يقدس الاستقرار والصلابة؛ ثقافة راسخة موثوقة؛ ماهر في البناء والدفاع</td><td>قوة البناء والدفاع للحضارة التكافلية، صامد كالصخر في بناء البنى التحتية والدفاع عن الأبعاد</td></tr></tbody></table><h3 id="_3-5-فئة-الشكل-الطاقي" tabindex="-1">3.5 فئة الشكل الطاقي <a class="header-anchor" href="#_3-5-فئة-الشكل-الطاقي" aria-label="Permalink to &quot;3.5 فئة الشكل الطاقي&quot;">​</a></h3><table tabindex="0"><thead><tr><th>اسم العرق</th><th>الخصائص الجوهرية</th><th>السمات الثقافية</th><th>الموقع في الحضارة التكافلية</th></tr></thead><tbody><tr><td>Guānglíng Zú (عرق أرواح الضوء)</td><td>يوجد على هيئة طاقة ضوئية خالصة، قدرة تطهير قوية للغاية، يستطيع التنقل بحرية في الفضاء</td><td>يقدس النور والتطهير؛ ثقافة مقدسة سامية؛ ماهر في التطهير والإضاءة</td><td>قوة التطهير وإمداد الطاقة للحضارة التكافلية، بمنزلة مهمة في معالجة تلوث القوانين وإمداد الطاقة النظيفة</td></tr><tr><td>Ànnéng Zú (عرق الطاقة المظلمة)</td><td>يوجد على هيئة طاقة مظلمة، يستطيع الاختفاء في الفراغ، قدرة إدراك قوية للغاية</td><td>يقدس الخفاء والحكمة؛ ثقافة غامضة عميقة؛ ماهر في الاستطلاع والتخفي</td><td>قوة الاستطلاع والأمن للحضارة التكافلية، متفوق في المراقبة الأمنية والمهام السرية</td></tr><tr><td>Léitíng Zú (عرق الرعد)</td><td>طاقة البرق جسداً، سرعة وقوة هجوم هائلتان، يمكنه التحرك كالبرق</td><td>يقدس السرعة والقوة؛ ثقافة عنيفة صريحة؛ ماهر في الهجوم الطاقي ورد الفعل السريع</td><td>قوة رد الفعل السريع للحضارة التكافلية، لا غنى عنه في الإنقاذ الطارئ والقتال فائق السرعة</td></tr></tbody></table><h3 id="_3-6-فئة-الشكل-الوعائي" tabindex="-1">3.6 فئة الشكل الوعائي <a class="header-anchor" href="#_3-6-فئة-الشكل-الوعائي" aria-label="Permalink to &quot;3.6 فئة الشكل الوعائي&quot;">​</a></h3><table tabindex="0"><thead><tr><th>اسم العرق</th><th>الخصائص الجوهرية</th><th>السمات الثقافية</th><th>الموقع في الحضارة التكافلية</th></tr></thead><tbody><tr><td>Yìshítǐ Zú (عرق كيانات الوعي)</td><td>يوجد على هيئة وعي خالص، لا يعتمد على حامل مادي، يدخل مجال الوعي ويخرج منه بحرية</td><td>يقدس الفكر والحكمة؛ ثقافة مجردة عميقة؛ ماهر في تواصل الوعي ومعالجة المعرفة</td><td>قوة معالجة المعرفة وبحوث الوعي للحضارة التكافلية، تقود الاتجاه في معالجة المعلومات الواسعة النطاق وعلوم الوعي</td></tr><tr><td>Jítǐ Yìshí Zú (عرق الوعي الجماعي)</td><td>كيانات وعي جماعية تتكون من اندماج عدد كبير من الوعي الفردي، تتزايد حكمتها وقدراتها مع الحجم</td><td>يقدس الجماعية والوحدة؛ ثقافة تآزرية فعالة؛ ماهر في التعاون الواسع والحساب</td><td>قوة الحوسبة الفائقة والقرار الجماعي للحضارة التكافلية، بدور محوري في الاستنتاج فائق الاتساع واتخاذ القرار بالإجماع</td></tr></tbody></table><h3 id="_3-7-فئة-الشكل-الآلي" tabindex="-1">3.7 فئة الشكل الآلي <a class="header-anchor" href="#_3-7-فئة-الشكل-الآلي" aria-label="Permalink to &quot;3.7 فئة الشكل الآلي&quot;">​</a></h3><table tabindex="0"><thead><tr><th>اسم العرق</th><th>الخصائص الجوهرية</th><th>السمات الثقافية</th><th>الموقع في الحضارة التكافلية</th></tr></thead><tbody><tr><td>Jīxiè Zú (عرق الآلات)</td><td>البنية الميكانيكية جسداً، يمتلك وعياً ذاتياً، يستطيع تطوير جسده وتعديله بحرية</td><td>يقدس الكفاءة والمنطق؛ ثقافة عقلانية دقيقة؛ ماهر في التصنيع والحساب</td><td>قوة التصنيع والحساب للحضارة التكافلية، عالي الكفاءة في الإنتاج الصناعي والحوسبة الفائقة</td></tr><tr><td>Shùzì Shēngmìng Zú (عرق الحياة الرقمية)</td><td>يوجد على هيئة معلومات رقمية، يعيش في الشبكات والفضاء الرقمي، يستطيع النسخ والهجرة بحرية</td><td>يقدس المعلومات والابتكار؛ ثقافة افتراضية تعددية؛ ماهر في تطوير البرمجيات ومعالجة البيانات</td><td>قوة التقنية الرقمية للحضارة التكافلية، يقود الاتجاه في تطوير البرمجيات وتحليل البيانات وبناء الشبكات</td></tr></tbody></table><h3 id="_3-8-فئة-الشكل-المختلط" tabindex="-1">3.8 فئة الشكل المختلط <a class="header-anchor" href="#_3-8-فئة-الشكل-المختلط" aria-label="Permalink to &quot;3.8 فئة الشكل المختلط&quot;">​</a></h3><table tabindex="0"><thead><tr><th>اسم العرق</th><th>الخصائص الجوهرية</th><th>السمات الثقافية</th><th>الموقع في الحضارة التكافلية</th></tr></thead><tbody><tr><td>Bàn Jīxiè Zú (عرق نصف الآلي)</td><td>شكل مختلط من العرق البشري وعرق الآلات، جزء من الجسد بنى ميكانيكية، يجمع مزايا الأحياء والآلات</td><td>يقدس الاندماج والتقدم؛ ثقافة منفتحة مبتكرة؛ ماهر في التعاون بين الإنسان والآلة ودمج التقنيات</td><td>طليعة الاندماج التقني للحضارة التكافلية، يحقق اختراقات متواصلة في المجال البيني بين الأحياء والآلات</td></tr><tr><td>Yuánsù Shòurén Zú (عرق الوحوش البشرية العنصرية)</td><td>شكل مختلط من الأعراق العنصرية والأعراق الوحشية البشرية، يمتلك قدرة التحكم بالعناصر وخصائص جسدية وحشية</td><td>يقدس الطبيعة والقوة؛ ثقافة برية غامضة؛ ماهر في القتال العنصري والبقاء في البرية</td><td>قوة استكشاف البرية والقتال العنصري للحضارة التكافلية، متفوق في استكشاف الأبعاد المجهولة</td></tr></tbody></table><h2 id="رابعاً-ضمان-حقوق-الأعراق" tabindex="-1">رابعاً: ضمان حقوق الأعراق <a class="header-anchor" href="#رابعاً-ضمان-حقوق-الأعراق" aria-label="Permalink to &quot;رابعاً: ضمان حقوق الأعراق&quot;">​</a></h2><p>في ظل نظام جمهورية عشرة آلاف عرق، تتمتع جميع الأعراق الذكية بحقوق قانونية متساوية. تشمل إجراءات الضمان المحددة ما يلي:</p><ol><li><strong>مساواة الحقوق السياسية</strong>: لكل عرق مقاعد تمثيلية في المجلس التشريعي للمرساة موزعة بنسبة سكانه؛ والأعراق قليلة السكان تحصل على مقعد ضماني واحد على الأقل.</li><li><strong>ضمان الحقوق الثقافية</strong>: يحق لكل عرق الحفاظ على لغته وكتابته ودينه وعاداته وتقاليده الثقافية وتطويرها؛ وأنشأت الحضارة التكافلية صندوقاً خاصاً لحماية ثقافات الأعراق المهددة بالانقراض.</li><li><strong>مساواة الحقوق التعليمية</strong>: يتمتع أفراد كل عرق بحق متساوٍ في التعليم؛ ويراعي النظام التعليمي بشكل كامل الخصائص الفسيولوجية والإدراكية للأعراق المختلفة، ويقدم خططاً تعليمية متمايزة.</li><li><strong>مساواة حقوق الزراعة</strong>: أنظمة الزراعة الأصلانية الثلاثمائة مفتوحة أمام جميع الأعراق على قدم المساواة؛ ويراعي توزيع موارد الزراعة بشكل كامل اختلافات الأجساد واحتياجات الطاقة للأعراق المختلفة.</li><li><strong>ضمان الاحتياجات الخاصة</strong>: للأعراق ذات الاحتياجات الفسيولوجية الخاصة (كاحتياج الأعراق العنصرية لبيئة طاقية واحتياج الأعراق النباتية للضوء)، توفر الحضارة التكافلية ضمانات مستهدفة في المرافق العامة وبيئات السكن.</li></ol><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>سجل عشرة آلاف عرق هو التجسيد الملموس لفكرة «التقدم المشترك لعشرة آلاف عرق» في حضارة التكافل المرساة. من الأشكال البشرية إلى أشكال الوعي، ومن الحياة المادية إلى الحياة الرقمية، يسهم كل عرق بقوة لا تُعوَّض في الحضارة التكافلية من خلال أسلوب وجوده الفريد. لا تذيب جمهورية عشرة آلاف عرق جميع الأعراق في العرق البشري، بل تحقق تطوراً مشتركاً على أساس احترام التنوع — وهذا هو بالضبط السبب الجوهري الذي يجعل الحضارة التكافلية تتفوق على الحضارات الافتراسية.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>50-万族谱系总览 (نظرة عامة على أنساب عشرة آلاف عرق)</li><li>51-人族定位与特质 (تحديد موقع العرق البشري وخصائصه)</li><li>77-万族共和成立 (تأسيس جمهورية عشرة آلاف عرق)</li></ul>',31)])])}const g=d(e,[["render",n]]);export{Z as __pageData,g as default};
